import{_ as t,o as i,c as l,a3 as o}from"./chunks/framework.BrO6lPIi.js";const p=JSON.parse('{"title":"交互操作工具","description":"本文件面向“交互操作工具”这一扩展端内容脚本能力，聚焦以下目标：。","frontmatter":{"title":"交互操作工具","description":"本文件面向“交互操作工具”这一扩展端内容脚本能力，聚焦以下目标：。"},"headers":[],"relativePath":"网页增强工具/交互操作工具/index.md","filePath":"网页增强工具/交互操作工具/index.md","lastUpdated":null}'),r={name:"网页增强工具/交互操作工具/index.md"};function n(a,e,c,s,u,h){return i(),l("div",null,[...e[0]||(e[0]=[o(`<h1 id="交互操作工具" tabindex="-1">交互操作工具 <a class="header-anchor" href="#交互操作工具" aria-label="Permalink to &quot;交互操作工具&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js" target="_blank" rel="noreferrer">src/content/interaction-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js" target="_blank" rel="noreferrer">src/content/page-interaction.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js" target="_blank" rel="noreferrer">src/content/page-utils.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与稳定性">性能与稳定性</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录典型交互场景">附录：典型交互场景</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件面向“交互操作工具”这一扩展端内容脚本能力，聚焦以下目标：</p><ul><li>元素定位与点击：支持 CSS 选择器、Shadow DOM 穿透、ref 引用、文本匹配；提供可见性检测、自动等待页面稳定。</li><li>表单填写与提交：输入框填充、富文本编辑器兼容、下拉菜单选择、单选/复选框操作、文件上传模拟、自动触发 change/input 事件。</li><li>滚动与导航控制：平滑滚动、视口定位、按文本滚动、无限滚动内容收集、滚动边界判定。</li><li>键盘输入模拟：按键事件触发、组合键修饰符、输入法与富文本兼容性、无障碍名称解析。</li><li>复杂用户交互示例：自动化登录流程、数据录入任务、页面导航与叠加层操作。</li><li>错误处理策略、超时控制与性能优化建议。</li></ul><p>该能力位于 Chrome 扩展的内容脚本层，通过 <code>src/content</code> 下的模块实现，供上层工具编排调用。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>交互操作相关代码集中在内容脚本目录中，采用“功能域 + 共享工具”的组织方式：</p><ul><li><code>interaction-tools.js</code>：对外暴露的原子交互工具（点击、表单、滚动、等待、键盘、文件上传、下拉选择、存储管理）。</li><li><code>page-interaction.js</code>：元素查询、ref 引用、可交互元素快照、按 ref 操作、滚动到文本等。</li><li><code>page-utils.js</code>：通用工具（唯一选择器生成、DOM 签名、auto-wait、原生值设置、富文本填充）。</li><li><code>shadow-dom-utils.js</code>：Shadow DOM 穿透查询。</li><li><code>demo-product-form.e2e.spec.js</code>：端到端用例，演示多步骤表单、模态框、叠加层与 ref 操作。</li></ul><pre class="mermaid">graph TB
subgraph &quot;内容脚本&quot;
IT[&quot;interaction-tools.js&lt;br/&gt;点击/表单/滚动/等待/键盘/上传/下拉/存储&quot;]
PI[&quot;page-interaction.js&lt;br/&gt;元素快照/ref/滚动到文本/按ref操作&quot;]
PU[&quot;page-utils.js&lt;br/&gt;选择器/DOM签名/auto-wait/原生值/富文本&quot;]
SDU[&quot;shadow-dom-utils.js&lt;br/&gt;Shadow DOM 穿透查询&quot;]
end
IT --&gt; PU
IT --&gt; SDU
IT --&gt; PI
PI --&gt; PU
PI --&gt; SDU
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L1-L10" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L1-L10" target="_blank" rel="noreferrer">src/content/page-interaction.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L1-L10" target="_blank" rel="noreferrer">src/content/page-utils.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L1-L10" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L1-L10" target="_blank" rel="noreferrer">src/content/page-interaction.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L1-L10" target="_blank" rel="noreferrer">src/content/page-utils.js#L1-L10</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>本节从“能力维度”梳理工具集，并给出关键函数入口与行为要点。</p><ul><li><p>元素定位与点击</p><ul><li><code>clickElement(selector, waitTime, timeout)</code>：CSS 选择器点击，自动等待 URL/DOM 变化稳定。</li><li><code>clickByText(text, options)</code>：按文本查找可交互元素并点击或悬停，返回匹配诊断信息。</li><li><code>interactByRef(ref, action, options)</code>：基于 query_elements 返回的 ref 编号执行 click/hover/type。</li><li><code>getElementCount(selector, includeHidden)</code>：快速统计元素数量（含可见计数）。</li></ul></li><li><p>表单填写与提交</p><ul><li><code>fillForm(fields, waitTime)</code>：批量填充 text/select/checkbox/radio/contenteditable，统一派发 input/change 事件。</li><li><code>selectDropdown(triggerSelector, optionText, optionSelector, timeout)</code>：原生 select 与自定义下拉选择。</li><li><code>typeIntoElement(el, value, options)</code>：内部原子输入（聚焦、清空、写入、可选 Enter 提交）。</li></ul></li><li><p>滚动与导航</p><ul><li><code>scrollToPosition(options)</code>：top/bottom/coordinates/selector 滚动，支持 smooth 行为与边界判定。</li><li><code>scrollToText(text, options)</code>：滚动直到找到包含指定文本的元素并定位到视口中心。</li><li><code>scrollAndCollect(args)</code>：无限滚动内容收集，去重后返回可视文本。</li></ul></li><li><p>可见性与等待</p><ul><li><code>waitForElement(selector, state, timeout)</code>：等待 appeared/disappeared/visible/hidden 状态。</li><li><code>isElementTrulyVisible(el)</code>：严格可见性判断（display/visibility/opacity/尺寸/视口）。</li><li><code>autoWaitAfterAction(sigBefore, minWait, maxWait)</code>：操作后自动等待页面稳定。</li></ul></li><li><p>键盘输入模拟</p><ul><li><code>keyboardInput({ key, text, ctrlKey, shiftKey, altKey })</code>：模拟按键与文本输入，兼容富文本与 React 受控组件。</li></ul></li><li><p>文件上传</p><ul><li><code>fileUpload(selector, fileName, fileContent, fileType)</code>：构造 File/Blob/DataTransfer 并触发 change。</li></ul></li><li><p>存储管理</p><ul><li><code>manageStorage({ action, storage, key, value })</code>：localStorage/sessionStorage 的 get/set/remove/clear。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L100-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L100-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L150-L241" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L150-L241</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L243-L281" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L243-L281</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L283-L359" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L283-L359</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L361-L476" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L361-L476</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L478-L522" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L478-L522</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L524-L657" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L524-L657</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L659-L739" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L659-L739</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L741-L786" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L741-L786</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L776-L899" target="_blank" rel="noreferrer">src/content/page-interaction.js#L776-L899</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L901-L983" target="_blank" rel="noreferrer">src/content/page-interaction.js#L901-L983</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L184-L245" target="_blank" rel="noreferrer">src/content/page-utils.js#L184-L245</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L247-L305" target="_blank" rel="noreferrer">src/content/page-utils.js#L247-L305</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>交互操作工具的整体调用链如下：上层工具编排（如 Agent 工具）→ 内容脚本工具 → DOM 操作与事件分发 → auto-wait 等待页面稳定。</p><pre class="mermaid">sequenceDiagram
participant Caller as &quot;上层工具&quot;
participant IT as &quot;interaction-tools.js&quot;
participant PI as &quot;page-interaction.js&quot;
participant PU as &quot;page-utils.js&quot;
participant DOM as &quot;浏览器DOM&quot;
Caller-&gt;&gt;IT : 调用 clickElement/fillForm/keyboardInput
IT-&gt;&gt;DOM : deepQuerySelector / element.click() / dispatchEvent
IT-&gt;&gt;PU : getDomSignature()
IT-&gt;&gt;PU : autoWaitAfterAction(sigBefore, minWait, maxWait)
PU--&gt;&gt;IT : {changed,urlChanged,domChanged,waitedMs}
IT--&gt;&gt;Caller : 结果对象{success,message,...}
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L100-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L100-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L184-L245" target="_blank" rel="noreferrer">src/content/page-utils.js#L184-L245</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="元素定位与点击" tabindex="-1">元素定位与点击 <a class="header-anchor" href="#元素定位与点击" aria-label="Permalink to &quot;元素定位与点击&quot;">​</a></h3><ul><li>选择器支持 <ul><li>使用 <code>deepQuerySelector</code> 穿透 Shadow DOM，避免现代 Web Components 导致的定位失败。</li><li>支持 CSS 选择器；XPath 未直接暴露，但可通过 CSS 表达常见定位需求。</li></ul></li><li>可见性检测 <ul><li><code>isElementTrulyVisible</code> 综合 display/visibility/opacity/尺寸/视口判定，避免点到隐藏元素。</li></ul></li><li>点击与自动等待 <ul><li><code>clickElement</code> 记录点击前 DOM 签名，点击后调用 <code>autoWaitAfterAction</code> 等待 URL/DOM 稳定。</li><li><code>clickByText</code> 遍历可交互元素集合，精确/包含匹配文本，返回诊断信息（是否存在、是否隐藏、是否可点击）。</li></ul></li><li>Ref 引用 <ul><li><code>queryInteractiveElements</code> 输出树形快照并为每个元素分配稳定 ref；<code>interactByRef</code> 通过 WeakMap 跨快照复用编号，失效时回退 selector 重查。</li></ul></li></ul><pre class="mermaid">flowchart TD
Start([&quot;开始&quot;]) --&gt; ParseSel[&quot;清理选择器/解析ref&quot;]
ParseSel --&gt; FindEl[&quot;deepQuerySelector 查找元素&quot;]
FindEl --&gt; Found{&quot;找到元素?&quot;}
Found --&gt; |否| ReturnErr[&quot;返回未找到错误&quot;]
Found --&gt; |是| CheckVis[&quot;检查可见性&quot;]
CheckVis --&gt; ClickOrHover[&quot;click()/hover()&quot;]
ClickOrHover --&gt; Sig[&quot;getDomSignature()&quot;]
Sig --&gt; AutoWait[&quot;autoWaitAfterAction(minWait,maxWait)&quot;]
AutoWait --&gt; Result[&quot;返回成功+变化提示&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L100-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L100-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L524-L657" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L524-L657</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L776-L857" target="_blank" rel="noreferrer">src/content/page-interaction.js#L776-L857</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L184-L245" target="_blank" rel="noreferrer">src/content/page-utils.js#L184-L245</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L100-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L100-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L524-L657" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L524-L657</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L776-L857" target="_blank" rel="noreferrer">src/content/page-interaction.js#L776-L857</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L184-L245" target="_blank" rel="noreferrer">src/content/page-utils.js#L184-L245</a></li></ul><h3 id="表单填写与提交机制" tabindex="-1">表单填写与提交机制 <a class="header-anchor" href="#表单填写与提交机制" aria-label="Permalink to &quot;表单填写与提交机制&quot;">​</a></h3><ul><li>输入框填充 <ul><li>标准 input/textarea：通过 <code>setNativeValue</code> 绕过 React 受控组件监听，再派发 input/change 事件。</li><li>富文本编辑器：<code>fillContentEditable</code> 优先 execCommand(&#39;insertText&#39;)，否则回退 textContent，并派发 input/change。</li></ul></li><li>下拉菜单选择 <ul><li>原生 <code>&lt;select&gt;</code>：匹配 option.value 或 option.text，设置 value 并派发 change/input。</li><li>自定义下拉：点击触发器，轮询选项容器匹配文本，点击匹配项。</li></ul></li><li>复选框/单选按钮 <ul><li>checkbox：设置 checked 并派发 change。</li><li>radio：支持 selector[value=x] 或同 name/value 组内查找，设置 checked 并派发 change。</li></ul></li><li>文件上传 <ul><li>构造 Blob/File，通过 DataTransfer 赋值 input.files，派发 change。</li></ul></li><li>自动提交 <ul><li><code>typeIntoElement</code> 支持 submit=true 时派发 Enter 键序列（keydown/keypress/keyup），触发表单提交。</li></ul></li></ul><pre class="mermaid">flowchart TD
FStart([&quot;fillForm/selectDropdown/fileUpload&quot;]) --&gt; TypeCheck{&quot;字段类型&quot;}
TypeCheck --&gt; |text| NativeVal[&quot;setNativeValue + input/change&quot;]
TypeCheck --&gt; |contenteditable| RichFill[&quot;fillContentEditable + input/change&quot;]
TypeCheck --&gt; |select| SelectMatch[&quot;匹配option并派发change/input&quot;]
TypeCheck --&gt; |checkbox| SetChecked[&quot;checked=true + change&quot;]
TypeCheck --&gt; |radio| RadioGroup[&quot;按name/value组选中 + change&quot;]
NativeVal --&gt; FEnd([&quot;完成&quot;])
RichFill --&gt; FEnd
SelectMatch --&gt; FEnd
SetChecked --&gt; FEnd
RadioGroup --&gt; FEnd
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L150-L241" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L150-L241</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L659-L739" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L659-L739</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L478-L522" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L478-L522</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L859-L899" target="_blank" rel="noreferrer">src/content/page-interaction.js#L859-L899</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L247-L305" target="_blank" rel="noreferrer">src/content/page-utils.js#L247-L305</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L150-L241" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L150-L241</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L659-L739" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L659-L739</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L478-L522" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L478-L522</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L859-L899" target="_blank" rel="noreferrer">src/content/page-interaction.js#L859-L899</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L247-L305" target="_blank" rel="noreferrer">src/content/page-utils.js#L247-L305</a></li></ul><h3 id="滚动与导航控制" tabindex="-1">滚动与导航控制 <a class="header-anchor" href="#滚动与导航控制" aria-label="Permalink to &quot;滚动与导航控制&quot;">​</a></h3><ul><li>平滑滚动与视口定位 <ul><li><code>scrollToPosition</code> 支持 top/bottom/coordinates/selector，behavior=smooth，block=center/left/right/top/bottom。</li><li>边界判定：已在顶部/底部/坐标位置时标记 moved=false，便于循环检测器识别无进展。</li></ul></li><li>按文本滚动 <ul><li><code>scrollToText</code> 先检查当前视口，若未命中则循环 scrollBy 并 pause，最终 scrollIntoView 居中。</li></ul></li><li>无限滚动内容收集 <ul><li><code>scrollAndCollect</code> 按固定像素滚动，收集可视文本节点，去重相邻重复行，最后滚回起始位置。</li></ul></li></ul><pre class="mermaid">flowchart TD
SStart([&quot;scrollToPosition/scrollToText&quot;]) --&gt; Target{&quot;目标类型&quot;}
Target --&gt; |top/bottom| Boundary[&quot;边界判定 + scrollTo&quot;]
Target --&gt; |coordinates| ScrollCoord[&quot;scrollTo(x,y)&quot;]
Target --&gt; |selector| ScrollElem[&quot;scrollIntoView(behavior, block)&quot;]
Boundary --&gt; SEnd([&quot;完成&quot;])
ScrollCoord --&gt; SEnd
ScrollElem --&gt; SEnd
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L243-L281" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L243-L281</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L901-L983" target="_blank" rel="noreferrer">src/content/page-interaction.js#L901-L983</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L243-L281" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L243-L281</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L901-L983" target="_blank" rel="noreferrer">src/content/page-interaction.js#L901-L983</a></li></ul><h3 id="键盘输入模拟" tabindex="-1">键盘输入模拟 <a class="header-anchor" href="#键盘输入模拟" aria-label="Permalink to &quot;键盘输入模拟&quot;">​</a></h3><ul><li>按键映射 <ul><li>KEY_CODE_MAP 提供常用键映射（Enter/Escape/Tab/Backspace/Delete/方向键/Home/End/PageUp/PageDown/Space/F1-F12）。</li><li>字母/数字动态计算 code/keyCode，F键按规则计算 keyCode。</li></ul></li><li>文本输入 <ul><li>对 contenteditable：execCommand(&#39;selectAll&#39;/&#39;insertText&#39;) 或 fallback textContent。</li><li>对 input/textarea：setNativeValue + InputEvent(inputType=&#39;insertText&#39;) + change。</li></ul></li><li>组合键 <ul><li>支持 ctrlKey/shiftKey/altKey 修饰符，派发 keydown/keypress/keyup 三件套。</li></ul></li><li>自动等待 <ul><li>输入后调用 autoWaitAfterAction，检测导航或 DOM 变化并返回变化提示。</li></ul></li></ul><pre class="mermaid">flowchart TD
KStart([&quot;keyboardInput&quot;]) --&gt; ActiveEl[&quot;获取activeElement&quot;]
ActiveEl --&gt; HasText{&quot;有text?&quot;}
HasText --&gt; |是| Editable{&quot;是否可编辑?&quot;}
Editable --&gt; |富文本| RichInput[&quot;execCommand insertText/textContent&quot;]
Editable --&gt; |标准输入| NativeInput[&quot;setNativeValue + InputEvent + change&quot;]
HasText --&gt; |否| KeyOnly[&quot;仅按键&quot;]
KeyOnly --&gt; MapKey[&quot;KEY_CODE_MAP 映射&quot;]
MapKey --&gt; Dispatch[&quot;派发 keydown/keypress/keyup&quot;]
RichInput --&gt; AutoWait[&quot;autoWaitAfterAction&quot;]
NativeInput --&gt; AutoWait
Dispatch --&gt; AutoWait
AutoWait --&gt; KEnd([&quot;返回成功+变化提示&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L361-L476" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L361-L476</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L247-L305" target="_blank" rel="noreferrer">src/content/page-utils.js#L247-L305</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L361-L476" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L361-L476</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L247-L305" target="_blank" rel="noreferrer">src/content/page-utils.js#L247-L305</a></li></ul><h3 id="可见性检测与异步等待" tabindex="-1">可见性检测与异步等待 <a class="header-anchor" href="#可见性检测与异步等待" aria-label="Permalink to &quot;可见性检测与异步等待&quot;">​</a></h3><ul><li>严格可见性 <ul><li><code>isElementTrulyVisible</code> 检查 offsetParent/display/visibility/opacity/尺寸/视口，确保元素真正可见。</li></ul></li><li>状态等待 <ul><li><code>waitForElement</code> 轮询 appeared/disappeared/visible/hidden，超时返回结构化错误。</li></ul></li><li>操作后自动等待 <ul><li><code>autoWaitAfterAction</code> 先等待最小时间，期间检测 DOM 签名变化，连续两次无变化视为稳定。</li></ul></li></ul><pre class="mermaid">flowchart TD
WStart([&quot;waitForElement&quot;]) --&gt; Poll[&quot;每100ms检查元素状态&quot;]
Poll --&gt; State{&quot;达到期望状态?&quot;}
State --&gt; |是| Resolve[&quot;resolve成功结果&quot;]
State --&gt; |否| Timeout{&quot;超过timeout?&quot;}
Timeout --&gt; |是| Reject[&quot;resolve失败+超时错误&quot;]
Timeout --&gt; |否| Poll
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L283-L359" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L283-L359</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L184-L245" target="_blank" rel="noreferrer">src/content/page-utils.js#L184-L245</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L283-L359" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L283-L359</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L184-L245" target="_blank" rel="noreferrer">src/content/page-utils.js#L184-L245</a></li></ul><h3 id="复杂用户交互场景示例" tabindex="-1">复杂用户交互场景示例 <a class="header-anchor" href="#复杂用户交互场景示例" aria-label="Permalink to &quot;复杂用户交互场景示例&quot;">​</a></h3><ul><li>自动化登录流程 <ul><li>步骤：定位用户名/密码输入框 → fillForm 填充 → 点击登录按钮 → waitForElement 等待登录成功标志 → 跳转检测。</li><li>关键点：使用 <code>autoWaitAfterAction</code> 捕获导航变化；使用 <code>isElementTrulyVisible</code> 验证登录成功元素可见。</li></ul></li><li>数据录入任务 <ul><li>步骤：fillForm 批量填充 → selectDropdown 选择分类 → fileUpload 上传附件 → interactByRef 提交。</li><li>关键点：表单字段类型区分（text/select/checkbox/radio/contenteditable）；文件上传需校验 input.type===&#39;file&#39;。</li></ul></li><li>页面导航与叠加层操作 <ul><li>步骤：queryInteractiveElements 获取快照 → 打开模态框 → 在叠加层内定位确认按钮 → interactByRef 勾选条款 → 点击确认。</li><li>关键点：叠加层根判定（dialog/popover/menu/listbox）；ref 跨快照复用与失效回退。</li></ul></li></ul><p>参考端到端用例：</p><ul><li>商品录入 Demo：多步向导、模态框、双语切换、列表追加、重置、叠加层 ref 操作。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js#L24-L51" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js#L24-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js#L113-L151" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js#L113-L151</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>模块耦合 <ul><li>interaction-tools.js 依赖 page-utils.js（DOM签名、auto-wait、原生值、富文本）、shadow-dom-utils.js（Shadow DOM 穿透）、page-interaction.js（ref 解析）。</li><li>page-interaction.js 依赖 page-utils.js 与 shadow-dom-utils.js，并提供 queryInteractiveElements、interactByRef、scrollToText。</li></ul></li><li>外部依赖 <ul><li>浏览器 API：document.querySelector/querySelectorAll、window.scrollTo/scrollBy、DataTransfer、File/Blob、KeyboardEvent/InputEvent/MouseEvent。</li></ul></li><li>潜在循环依赖 <ul><li>interaction-tools.js 与 page-interaction.js 存在相互引用（如 getElementByRef），但通过按需导入避免加载期循环。</li></ul></li></ul><pre class="mermaid">graph LR
IT[&quot;interaction-tools.js&quot;] --&gt; PU[&quot;page-utils.js&quot;]
IT --&gt; SDU[&quot;shadow-dom-utils.js&quot;]
IT --&gt; PI[&quot;page-interaction.js&quot;]
PI --&gt; PU
PI --&gt; SDU
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L1-L6" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L1-L7" target="_blank" rel="noreferrer">src/content/page-interaction.js#L1-L7</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L1-L5" target="_blank" rel="noreferrer">src/content/page-utils.js#L1-L5</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L1-L6" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L1-L7" target="_blank" rel="noreferrer">src/content/page-interaction.js#L1-L7</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-utils.js#L1-L5" target="_blank" rel="noreferrer">src/content/page-utils.js#L1-L5</a></li></ul><h2 id="性能与稳定性" tabindex="-1">性能与稳定性 <a class="header-anchor" href="#性能与稳定性" aria-label="Permalink to &quot;性能与稳定性&quot;">​</a></h2><ul><li>性能优化建议 <ul><li>优先使用 ref 引用而非复杂 CSS 选择器，减少选择器计算开销。</li><li>使用 <code>getElementCount</code> 快速判断元素存在性，避免不必要的 DOM 遍历。</li><li>合理使用 <code>autoWaitAfterAction</code> 的最小/最大等待，避免过长阻塞。</li><li>无限滚动时使用 <code>scrollAndCollect</code> 的去重逻辑，减少重复内容处理。</li></ul></li><li>稳定性保障 <ul><li>所有工具返回结构化结果对象 <code>{success, message?, error?, ...}</code>，便于上层统一处理。</li><li>可见性检测与叠加层根判定避免误操作隐藏元素或嵌套层。</li><li>ref 失效时提供附近有效引用建议，辅助上层重试或重新查询。</li></ul></li></ul><p>[本节为通用指导，不直接分析具体文件]</p><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>元素未找到 <ul><li>检查选择器是否正确，是否被 Shadow DOM 包裹；尝试使用 queryInteractiveElements 获取最新快照与 ref。</li><li>对于 clickByText，确认文本是否存在、是否可见、是否在可交互元素中。</li></ul></li><li>表单填充无效 <ul><li>确认字段类型（text/select/checkbox/radio/contenteditable），富文本编辑器需使用 fillContentEditable。</li><li>检查 React 受控组件是否通过 setNativeValue 正确更新值。</li></ul></li><li>点击无响应 <ul><li>检查元素可见性（display/visibility/opacity/尺寸/视口），确保未被隐藏或折叠。</li><li>使用 interactByRef 替代 CSS 选择器，避免选择器失效。</li></ul></li><li>滚动无进展 <ul><li>检查滚动目标是否为 document.scrollingElement 或指定容器；确认已到达边界。</li></ul></li><li>键盘输入失败 <ul><li>确认 activeElement 存在且可编辑；富文本编辑器需兼容 execCommand。</li></ul></li><li>文件上传失败 <ul><li>校验 input.type===&#39;file&#39;；确保 fileContent 为 base64 或文本；确认 DataTransfer 赋值成功。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L100-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L100-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L150-L241" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L150-L241</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L524-L657" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L524-L657</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L776-L857" target="_blank" rel="noreferrer">src/content/page-interaction.js#L776-L857</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>交互操作工具通过内容脚本层提供了完整的页面交互能力，涵盖元素定位、点击、表单填写、滚动导航、键盘模拟、文件上传与异步等待。其设计强调：</p><ul><li>强鲁棒性：严格可见性检测、叠加层识别、ref 引用与失效回退。</li><li>高兼容性：Shadow DOM 穿透、React 受控组件兼容、富文本编辑器支持。</li><li>可观测性：结构化结果对象、变化提示、附近引用建议。 在实际使用中，建议优先使用 ref 引用与 queryInteractiveElements，结合 autoWaitAfterAction 与 isElementTrulyVisible，构建稳定可靠的自动化流程。</li></ul><p>[本节为总结性内容，不直接分析具体文件]</p><h2 id="附录-典型交互场景" tabindex="-1">附录：典型交互场景 <a class="header-anchor" href="#附录-典型交互场景" aria-label="Permalink to &quot;附录：典型交互场景&quot;">​</a></h2><ul><li>自动化登录流程 <ul><li>步骤：queryInteractiveElements → 定位用户名/密码 → fillForm → clickElement 登录 → waitForElement 等待成功标志。</li></ul></li><li>数据录入任务 <ul><li>步骤：fillForm 批量填充 → selectDropdown 选择分类 → fileUpload 上传附件 → interactByRef 提交。</li></ul></li><li>页面导航与叠加层操作 <ul><li>步骤：打开模态框 → queryInteractiveElements 获取叠加层 → interactByRef 勾选条款 → 点击确认。</li></ul></li></ul><p>参考端到端用例：</p><ul><li>商品录入 Demo：多步向导、模态框、双语切换、列表追加、重置、叠加层 ref 操作。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js#L24-L51" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js#L24-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js#L113-L151" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js#L113-L151</a></li></ul>`,92)])])}const b=t(r,[["render",n]]);export{p as __pageData,b as default};
